function i(t){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(t||"").trim())}function e(t){return/^0\d{9}$/.test(String(t||"").trim())}function r(t){const n=String(t||"").trim();if(!n)return!1;const s=n.replace(/[\s\-().]/g,"");return/^\+?\d{7,15}$/.test(s)}function a(t,n){return n==="GH"?e(t):r(t)}function o(t){const n=String(t||"");return n.length>=8&&/[A-Za-z]/.test(n)&&/\d/.test(n)}function d(t){const n=String(t||"");return n.length<8?"Password needs to be at least 8 characters.":!/[A-Za-z]/.test(n)||!/\d/.test(n)?"Password needs at least one letter and one number.":""}export{i as a,a as b,e as c,o as i,d as p};
